package com.tuap.backend.config;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties(prefix="app.email") public class EmailProperties { private boolean enabled=false; private String provider="resend"; private String from=""; private String passwordResetUrl=""; private String emailChangeConfirmUrl=""; private String resendApiKey=""; public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public String getProvider(){return provider;} public void setProvider(String v){provider=v;} public String getFrom(){return from;} public void setFrom(String v){from=v;} public String getPasswordResetUrl(){return passwordResetUrl;} public void setPasswordResetUrl(String v){passwordResetUrl=v;} public String getEmailChangeConfirmUrl(){return emailChangeConfirmUrl;} public void setEmailChangeConfirmUrl(String v){emailChangeConfirmUrl=v;} public String getResendApiKey(){return resendApiKey;} public void setResendApiKey(String v){resendApiKey=v;} }
